<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import type { EChartsOption } from 'echarts'
import { CircleClose, Plus, Refresh, Setting, VideoPause, VideoPlay } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import EChart from '@/components/charts/EChart.vue'
import MetricCard from '@/components/MetricCard.vue'
import PageHeader from '@/components/PageHeader.vue'
import SignalTag from '@/components/SignalTag.vue'
import { strategies } from '@/mock/strategies'
import { useQuantStore } from '@/stores/quant'
import { useQuoteSubscription } from '@/composables/useQuoteSubscription'
import { stocks } from '@/mock/stocks'
import type { PaperOrderStatus, QuantConfig, QuantLogLevel, QuantRunStatus } from '@/types/quant'

const route = useRoute()
const store = useQuantStore()
const quantUniverse = computed(() => [...new Set([...stocks.filter((stock) => stock.technicalScore >= 70 && stock.behaviorScore >= 60).map((stock) => stock.symbol), ...store.positions.map((row) => row.symbol), ...store.orders.filter((row) => row.status === 'PENDING').map((row) => row.symbol)])].slice(0, 80))
const liveQuotes = useQuoteSubscription(quantUniverse)
const tabs = ['总览', '我的策略', '实时模拟', '虚拟账户', '当前持仓', '订单', '成交', '风险', '绩效', '运行日志']
const activeTab = ref(typeof route.query.tab === 'string' && tabs.includes(route.query.tab) ? route.query.tab : '总览')
const navRange = ref('ALL')
const logFilter = ref<'ALL' | QuantLogLevel>('ALL')
const createDialog = ref(false)
const form = reactive<QuantConfig>({ ...store.config, strategyId: Number(route.query.strategy) || store.config.strategyId })
let timer: number | undefined

const statusMap: Record<QuantRunStatus, { label: string; tone: 'positive' | 'warning' | 'negative' | 'neutral' | 'info' }> = {
  DRAFT: { label: '草稿', tone: 'neutral' }, READY: { label: '准备就绪', tone: 'info' }, RUNNING: { label: '运行中', tone: 'positive' }, PAUSED: { label: '已暂停', tone: 'warning' }, STOPPED: { label: '已停止', tone: 'neutral' }, ERROR: { label: '运行错误', tone: 'negative' }, RISK_HALTED: { label: 'Risk Halted', tone: 'negative' },
}
const statusInfo = computed(() => statusMap[store.status])
const filteredLogs = computed(() => logFilter.value === 'ALL' ? store.logs : store.logs.filter((row) => row.level === logFilter.value))
const visibleNav = computed(() => {
  const sizes: Record<string, number> = { '1D': 12, '1W': 20, '1M': 32, '3M': 55, ALL: 1000 }
  return store.nav.slice(-sizes[navRange.value]!)
})
const navOption = computed<EChartsOption>(() => ({
  animationDuration: 350,
  grid: { top: 34, right: 24, bottom: 27, left: 50 },
  tooltip: { trigger: 'axis', valueFormatter: (value) => `${((Number(value) - 1) * 100).toFixed(2)}%` },
  legend: { top: 4, right: 18, data: ['策略净值', '沪深300（演示）'], textStyle: { color: '#777d88', fontSize: 10 }, itemWidth: 14, itemHeight: 7 },
  xAxis: { type: 'category', boundaryGap: false, data: visibleNav.value.map((row) => row.time), axisTick: { show: false }, axisLine: { lineStyle: { color: '#dfe1e6' } }, axisLabel: { color: '#8a909e', fontSize: 9, interval: 'auto' } },
  yAxis: { type: 'value', scale: true, axisLine: { show: false }, axisTick: { show: false }, splitLine: { lineStyle: { color: '#eef0f3' } }, axisLabel: { color: '#8a909e', fontSize: 9, formatter: (value: number) => `${((value - 1) * 100).toFixed(0)}%` } },
  series: [
    { name: '策略净值', type: 'line', data: visibleNav.value.map((row) => row.strategy), symbol: 'none', smooth: .25, lineStyle: { color: '#5555c9', width: 2 }, areaStyle: { color: 'rgba(85,85,201,.07)' } },
    { name: '沪深300（演示）', type: 'line', data: visibleNav.value.map((row) => row.benchmark), symbol: 'none', smooth: .25, lineStyle: { color: '#9aa0ad', width: 1.4, type: 'dashed' } },
  ],
}))
const drawdownOption = computed<EChartsOption>(() => ({
  grid: { top: 18, right: 18, bottom: 27, left: 46 }, tooltip: { trigger: 'axis', valueFormatter: (value) => `${value}%` },
  xAxis: { type: 'category', data: store.nav.map((row) => row.time), axisLine: { lineStyle: { color: '#dfe1e6' } }, axisTick: { show: false }, axisLabel: { color: '#8a909e', fontSize: 8 } },
  yAxis: { type: 'value', max: 0, axisLine: { show: false }, axisTick: { show: false }, splitLine: { lineStyle: { color: '#eef0f3' } }, axisLabel: { formatter: '{value}%', color: '#8a909e', fontSize: 8 } },
  series: [{ type: 'line', data: store.nav.map((row) => row.drawdown), symbol: 'none', lineStyle: { color: '#15966f', width: 1.5 }, areaStyle: { color: 'rgba(21,150,111,.10)' } }],
}))
const monthlyOption = computed<EChartsOption>(() => ({
  grid: { top: 20, right: 18, bottom: 27, left: 43 }, tooltip: { trigger: 'axis' },
  xAxis: { type: 'category', data: ['4月','5月','6月','7月','8月','9月'], axisTick: { show: false }, axisLine: { lineStyle: { color: '#dfe1e6' } }, axisLabel: { color: '#8a909e', fontSize: 9 } },
  yAxis: { type: 'value', axisLine: { show: false }, axisTick: { show: false }, splitLine: { lineStyle: { color: '#eef0f3' } }, axisLabel: { formatter: '{value}%', color: '#8a909e', fontSize: 8 } },
  series: [{ type: 'bar', barWidth: 20, data: [1.8,-.9,3.4,2.1,4.2,1.3].map((value) => ({ value, itemStyle: { color: value >= 0 ? '#d74444' : '#15966f', borderRadius: value >= 0 ? [3,3,0,0] : [0,0,3,3] } })) }],
}))

function money(value: number) { return `¥${value.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function pct(value: number) { return `${value > 0 ? '+' : ''}${value.toFixed(2)}%` }
function orderTone(status: PaperOrderStatus) { return status === 'FILLED' ? 'positive' : status === 'REJECTED' ? 'negative' : status === 'PENDING' || status === 'PARTIALLY_FILLED' ? 'warning' : 'neutral' }
function openCreate(strategyId?: number | Event) {
  const selectedStrategy = typeof strategyId === 'number' ? strategyId : (form.strategyId || Number(route.query.strategy) || store.config.strategyId)
  Object.assign(form, store.config)
  form.strategyId = selectedStrategy
  createDialog.value = true
}
function createInstance() { store.createInstance({ ...form }); createDialog.value = false; activeTab.value = '总览'; ElMessage.success('虚拟账户与策略实例已创建，可以启动模拟') }
function start() { store.start(); store.tick(liveQuotes.quotes, true); ElMessage.success('Live Paper 模拟已启动') }
function pause() { store.pause(); ElMessage.info('策略已暂停，新开仓已停止') }
function stop() { store.stop(); ElMessage.info('策略已停止') }
async function reset() { await ElMessageBox.confirm('将清空全部虚拟订单、成交和持仓，并恢复初始现金。该操作不会影响真实资产。', '重置虚拟账户', { type: 'warning' }); store.reset(); ElMessage.success('虚拟账户已重置') }
function cancel(id: string) { if (store.cancelOrder(id)) ElMessage.success('模拟订单已撤销') }

onMounted(() => { timer = window.setInterval(() => store.tick(liveQuotes.quotes), 2800) })
onBeforeUnmount(() => window.clearInterval(timer))
</script>

<template>
  <PageHeader title="量化实验室" description="真实或演示行情驱动的虚拟策略运行、模拟撮合、风控与绩效分析。">
    <SignalTag text="PAPER TRADING ONLY" tone="warning" />
    <button class="btn" @click="openCreate"><Plus />新建模拟</button>
    <button v-if="store.status !== 'RUNNING'" class="btn primary" :disabled="store.status === 'RISK_HALTED'" @click="start"><VideoPlay />启动模拟</button>
    <button v-else class="btn" @click="pause"><VideoPause />暂停</button>
  </PageHeader>

  <div class="paper-banner"><span><b>{{ liveQuotes.provider?.activeSource === 'ifind' ? 'iFinD 行情 / Paper Trading' : '演示行情 / Mock Paper Trading' }}</b>　所有订单、成交、资金和收益均为虚拟数据，不连接任何券商或真实账户。</span><span>{{ liveQuotes.provider?.activeSource || 'connecting' }} → 策略 → 风控 → 模拟撮合</span></div>

  <div v-if="store.status === 'RISK_HALTED'" class="risk-halted"><strong>Risk Halted</strong><span>{{ store.riskEvents[0]?.detail }}。系统已停止所有新开仓，请检查风险事件。</span><button @click="activeTab = '风险'">查看风险</button></div>

  <section class="quant-command panel">
    <div class="instance-identity"><span class="run-dot" :class="store.status.toLowerCase()" /><div><strong>{{ store.instance.strategyName }}</strong><small>{{ store.instance.id }} · LIVE PAPER · {{ store.config.timeframe }}</small></div></div>
    <div class="command-meta"><span>策略状态<strong><SignalTag :text="statusInfo.label" :tone="statusInfo.tone" /></strong></span><span>虚拟账户<strong>{{ store.instance.accountName }}</strong></span><span>运行开始<strong>{{ store.instance.startedAt || '尚未启动' }}</strong></span></div>
    <div class="command-actions"><button v-if="store.status !== 'RUNNING'" class="btn primary" :disabled="store.status === 'RISK_HALTED'" @click="start"><VideoPlay />启动</button><button v-else class="btn" @click="pause"><VideoPause />暂停</button><button class="btn" @click="stop"><CircleClose />停止</button><button class="btn danger" @click="reset"><Refresh />重置</button></div>
  </section>

  <nav class="quant-tabs panel" aria-label="量化实验室二级导航"><button v-for="item in tabs" :key="item" :class="{ active: activeTab === item }" @click="activeTab = item">{{ item }}<em v-if="item === '订单' && store.pendingOrders">{{ store.pendingOrders }}</em></button></nav>

  <template v-if="activeTab === '总览'">
    <div class="quant-metrics section-gap"><MetricCard label="当前资产" :value="money(store.totalAssets)" :change="pct(store.cumulativeReturn)" :tone="store.cumulativeReturn >= 0 ? 'positive' : 'negative'" hint="现金 + 持仓市值" /><MetricCard label="今日收益" :value="pct(store.todayReturn)" change="模拟盘" tone="positive" hint="按当前虚拟净值" /><MetricCard label="现金" :value="money(store.cash)" :change="`${(store.cash/store.totalAssets*100).toFixed(1)}%`" hint="可用于新开仓" /><MetricCard label="持仓市值" :value="money(store.marketValue)" :change="`${store.totalWeight.toFixed(1)}%`" hint="总仓位" /><MetricCard label="最大回撤" :value="pct(store.maxDrawdown)" :change="`阈值 -${store.config.maxDrawdown}%`" tone="negative" hint="触发 Kill Switch" /><MetricCard label="运行状态" :value="statusInfo.label" :change="`${store.positions.length} 持仓 · ${store.pendingOrders} 待成交`" hint="Live Paper" /></div>
    <div class="quant-overview section-gap">
      <section class="panel nav-panel"><div class="panel-head"><div><h2>策略净值 vs 基准</h2><p>虚拟成交驱动 · 基准为演示沪深300</p></div><div class="segmented"><button v-for="range in ['1D','1W','1M','3M','ALL']" :key="range" :class="{ active: navRange === range }" @click="navRange = range">{{ range }}</button></div></div><div class="chart-panel"><EChart :option="navOption" height="310px" /></div></section>
      <section class="panel signal-panel"><div class="panel-head"><div><h2>实时信号流</h2><p>{{ store.todaySignalCount }} 条演示信号</p></div><button class="text-button" @click="activeTab = '实时模拟'">查看全部</button></div><div class="signal-feed"><article v-for="signal in store.signals.slice(0,5)" :key="signal.id"><i :class="signal.type.toLowerCase()" /><div class="signal-time">{{ signal.time }}</div><div><strong>{{ signal.stockName }} <small>{{ signal.symbol.split('.')[1] }}</small></strong><p>{{ signal.reason.join(' · ') }}</p></div><SignalTag :text="`${signal.type} SIGNAL`" :tone="signal.type === 'BUY' ? 'positive' : signal.type === 'SELL' ? 'negative' : 'neutral'" /><span class="signal-state">{{ signal.status }}</span></article></div></section>
    </div>
    <div class="overview-bottom section-gap">
      <section class="panel"><div class="panel-head"><div><h2>当前虚拟持仓</h2><p>Paper Account，与手工持仓完全分离</p></div><button class="text-button" @click="activeTab = '当前持仓'">全部持仓</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>股票</th><th class="num">数量</th><th class="num">成本</th><th class="num">现价</th><th class="num">浮动盈亏</th><th class="num">收益率</th><th class="num">仓位</th><th>信号</th></tr></thead><tbody><tr v-for="row in store.positions" :key="row.symbol"><td><strong>{{ row.stockName }}</strong><small class="code-inline">{{ row.symbol }}</small></td><td class="num">{{ row.quantity }}</td><td class="num">{{ row.avgCost.toFixed(2) }}</td><td class="num">{{ row.price.toFixed(2) }}</td><td class="num" :class="row.pnl >= 0 ? 'positive' : 'negative'">{{ money(row.pnl) }}</td><td class="num" :class="row.returnPct >= 0 ? 'positive' : 'negative'">{{ pct(row.returnPct) }}</td><td class="num">{{ row.weight.toFixed(1) }}%</td><td><SignalTag :text="row.signal" tone="info" /></td></tr><tr v-if="!store.positions.length"><td colspan="8"><div class="empty-state">尚无虚拟持仓。启动模拟后，信号需先通过 Risk Engine 才会生成订单。</div></td></tr></tbody></table></div></section>
      <section class="panel"><div class="panel-head"><div><h2>执行与风险</h2><p>每个信号都有可解释路径</p></div></div><div class="pipeline"><div><b>1</b><span>Condition Engine<small>可视化规则</small></span></div><i>→</i><div><b>2</b><span>Risk Engine<small>仓位与回撤</small></span></div><i>→</i><div><b>3</b><span>Paper Broker<small>模拟订单</small></span></div><i>→</i><div><b>4</b><span>Exchange Simulator<small>成交条件</small></span></div></div><div class="risk-mini"><div><span>总仓位</span><strong>{{ store.totalWeight.toFixed(1) }} / {{ store.config.maxTotalWeight }}%</strong><i><b :style="{ width: `${Math.min(100, store.totalWeight/store.config.maxTotalWeight*100)}%` }" /></i></div><div><span>持仓数量</span><strong>{{ store.positions.length }} / {{ store.config.maxPositions }}</strong><i><b :style="{ width: `${store.positions.length/store.config.maxPositions*100}%` }" /></i></div><div><span>策略回撤</span><strong>{{ Math.abs(store.maxDrawdown).toFixed(2) }} / {{ store.config.maxDrawdown }}%</strong><i><b class="safe" :style="{ width: `${Math.min(100, Math.abs(store.maxDrawdown)/store.config.maxDrawdown*100)}%` }" /></i></div></div></section>
    </div>
  </template>

  <template v-else-if="activeTab === '我的策略'">
    <div class="quant-strategy-grid section-gap"><article v-for="strategy in strategies.slice(0,5)" :key="strategy.id" class="panel quant-strategy-card"><div><SignalTag :text="strategy.kind" :tone="strategy.kind === '系统策略' ? 'info' : 'neutral'" /><SignalTag v-if="strategy.id === store.instance.strategyId" text="当前实例" tone="positive" /></div><h2>{{ strategy.name }}</h2><p>{{ strategy.description }}</p><div class="strategy-rule-list"><span v-for="tag in strategy.tags" :key="tag">{{ tag }}</span></div><footer><small>{{ strategy.conditionCount }} 个入场条件</small><button class="btn soft" @click="form.strategyId = strategy.id; openCreate()">加入量化实验室</button></footer></article></div>
  </template>

  <template v-else-if="activeTab === '实时模拟'">
    <div class="live-layout section-gap"><section class="panel"><div class="panel-head"><div><h2>Live Paper Signal Feed</h2><p>候选池行情推进 · 新信号必须经过风险检查</p></div><SignalTag :text="statusInfo.label" :tone="statusInfo.tone" /></div><div class="signal-feed full"><article v-for="signal in store.signals" :key="signal.id"><i :class="signal.type.toLowerCase()" /><div class="signal-time">{{ signal.time }}</div><div><strong>{{ signal.stockName }} <small>{{ signal.symbol }}</small></strong><p>{{ signal.reason.join(' · ') }}</p><small>Technical {{ signal.technicalScore }} · Behavior {{ signal.behaviorScore }} · 量比 {{ signal.volumeRatio }}</small></div><SignalTag :text="`${signal.type} SIGNAL`" :tone="signal.type === 'BUY' ? 'positive' : signal.type === 'SELL' ? 'negative' : 'neutral'" /><span class="signal-state">{{ signal.status }}</span></article></div></section><aside class="stack"><section class="panel runtime-card"><div class="panel-head"><div><h2>运行控制</h2><p>只有虚拟撮合权限</p></div></div><div class="panel-body"><div class="runtime-status"><span class="run-dot" :class="store.status.toLowerCase()" /><strong>{{ statusInfo.label }}</strong></div><dl><div><dt>运行模式</dt><dd>LIVE_PAPER</dd></div><div><dt>时间框架</dt><dd>{{ store.config.timeframe }}</dd></div><div><dt>行情来源</dt><dd>{{ liveQuotes.provider?.activeSource || '连接中' }}</dd></div><div><dt>候选池</dt><dd>{{ quantUniverse.length }} 只按需订阅</dd></div></dl><button v-if="store.status !== 'RUNNING'" class="btn primary full-btn" @click="start">启动模拟</button><button v-else class="btn full-btn" @click="pause">暂停模拟</button></div></section><section class="panel"><div class="panel-head"><div><h2>今日活动</h2></div></div><div class="activity-counts"><div><strong>{{ store.signals.length }}</strong><span>信号</span></div><div><strong>{{ store.orders.length }}</strong><span>订单</span></div><div><strong>{{ store.trades.length }}</strong><span>成交</span></div><div><strong>{{ store.riskEvents.length }}</strong><span>风险事件</span></div></div></section></aside></div>
  </template>

  <template v-else-if="activeTab === '虚拟账户'">
    <div class="account-layout section-gap"><section class="panel account-card"><div class="account-title"><span>PA</span><div><strong>{{ store.instance.accountName }}</strong><small>{{ store.instance.id }} · PAPER ACCOUNT</small></div><SignalTag :text="statusInfo.label" :tone="statusInfo.tone" /></div><div class="account-balance"><span>当前虚拟资产</span><strong>{{ money(store.totalAssets) }}</strong><em :class="store.cumulativeReturn >= 0 ? 'positive' : 'negative'">{{ pct(store.cumulativeReturn) }}</em></div><div class="account-breakdown"><div><span>初始资金</span><strong>{{ money(store.initialCash) }}</strong></div><div><span>可用现金</span><strong>{{ money(store.cash) }}</strong></div><div><span>持仓市值</span><strong>{{ money(store.marketValue) }}</strong></div><div><span>资金利用率</span><strong>{{ store.totalWeight.toFixed(1) }}%</strong></div></div></section><section class="panel account-help"><div class="panel-head"><div><h2>账户隔离</h2><p>虚拟账户与真实资产之间没有资金或订单通道</p></div></div><div class="panel-body"><p>该账户仅由 Paper Broker 写入，页面上的资产、订单和成交均不可发送至券商。重置只会清空当前演示实例。</p><button class="btn" @click="openCreate"><Plus />创建另一个虚拟账户</button><button class="btn danger" @click="reset"><Refresh />重置当前账户</button></div></section></div>
  </template>

  <template v-else-if="activeTab === '当前持仓'">
    <section class="panel section-gap"><div class="panel-head"><div><h2>Paper Positions</h2><p>行情变化会重新计算虚拟市值和浮动盈亏</p></div><span class="chart-legend-note">{{ store.positions.length }} 只 · 总仓位 {{ store.totalWeight.toFixed(1) }}%</span></div><div class="data-table-wrap"><table class="data-table wide-table"><thead><tr><th>股票</th><th class="num">持仓</th><th class="num">可用</th><th class="num">平均成本</th><th class="num">现价</th><th class="num">市值</th><th class="num">浮动盈亏</th><th class="num">收益率</th><th class="num">仓位</th><th class="num">Technical</th><th class="num">Behavior</th><th>策略信号</th></tr></thead><tbody><tr v-for="row in store.positions" :key="row.symbol"><td><strong>{{ row.stockName }}</strong><small class="code-inline">{{ row.symbol }}</small></td><td class="num">{{ row.quantity }}</td><td class="num">{{ row.available }}</td><td class="num">{{ row.avgCost.toFixed(2) }}</td><td class="num">{{ row.price.toFixed(2) }}</td><td class="num">{{ money(row.marketValue) }}</td><td class="num" :class="row.pnl >= 0 ? 'positive' : 'negative'">{{ money(row.pnl) }}</td><td class="num" :class="row.returnPct >= 0 ? 'positive' : 'negative'">{{ pct(row.returnPct) }}</td><td class="num">{{ row.weight.toFixed(1) }}%</td><td class="num score-number">{{ row.technicalScore }}</td><td class="num">{{ row.behaviorScore }}</td><td><SignalTag :text="row.signal" tone="info" /></td></tr></tbody></table></div></section>
  </template>

  <template v-else-if="activeTab === '订单'">
    <section class="panel section-gap"><div class="panel-head"><div><h2>Paper Orders</h2><p>模拟委托并不保证成交，未成交订单会保留原因</p></div><SignalTag text="NO REAL BROKER" tone="warning" /></div><div class="data-table-wrap"><table class="data-table wide-table"><thead><tr><th>时间</th><th>订单号</th><th>股票</th><th>方向</th><th>类型</th><th class="num">委托价</th><th class="num">数量</th><th class="num">成交数量</th><th>状态</th><th>原因</th><th>操作</th></tr></thead><tbody><tr v-for="row in store.orders" :key="row.id"><td class="mono muted">{{ row.time }}</td><td class="mono">{{ row.id }}</td><td><strong>{{ row.stockName }}</strong><small class="code-inline">{{ row.symbol }}</small></td><td :class="row.side === 'BUY' ? 'positive' : 'negative'">{{ row.side }}</td><td>{{ row.type }}</td><td class="num">{{ row.limitPrice?.toFixed(2) || '市价' }}</td><td class="num">{{ row.quantity }}</td><td class="num">{{ row.filledQuantity }}</td><td><SignalTag :text="row.status" :tone="orderTone(row.status)" /></td><td class="reason-cell">{{ row.reason }}</td><td><button v-if="['NEW','PENDING','PARTIALLY_FILLED'].includes(row.status)" class="text-button" @click="cancel(row.id)">撤销</button><span v-else class="muted">—</span></td></tr></tbody></table></div></section>
  </template>

  <template v-else-if="activeTab === '成交'">
    <section class="panel section-gap"><div class="panel-head"><div><h2>Paper Trades</h2><p>滑点与交易费用计入虚拟账户，每笔成交保留行情来源</p></div><span class="chart-legend-note">{{ store.trades.length }} 笔模拟成交</span></div><div class="data-table-wrap"><table class="data-table wide-table"><thead><tr><th>成交时间</th><th>成交号</th><th>股票</th><th>方向</th><th class="num">成交价格</th><th class="num">数量</th><th class="num">成交金额</th><th class="num">交易费用</th><th class="num">滑点影响</th><th>行情来源</th><th>行情时间</th><th>来源策略</th></tr></thead><tbody><tr v-for="row in store.trades" :key="row.id"><td class="mono muted">{{ row.time }}</td><td class="mono">{{ row.id }}</td><td><strong>{{ row.stockName }}</strong><small class="code-inline">{{ row.symbol }}</small></td><td :class="row.side === 'BUY' ? 'positive' : 'negative'">{{ row.side }}</td><td class="num">{{ row.price.toFixed(2) }}</td><td class="num">{{ row.quantity }}</td><td class="num">{{ money(row.amount) }}</td><td class="num">{{ money(row.fee) }}</td><td class="num">{{ money(row.slippage) }}</td><td>{{ row.marketDataSource || 'mock preset' }}</td><td class="mono muted">{{ row.marketQuoteTime || '—' }}</td><td>{{ row.strategyName }}</td></tr></tbody></table></div></section>
  </template>

  <template v-else-if="activeTab === '风险'">
    <div class="risk-layout section-gap"><section class="panel"><div class="panel-head"><div><h2>Risk Engine 参数</h2><p>位于 Signal 与 Order 之间，任何订单都不能绕过</p></div><button class="btn" @click="openCreate"><Setting />修改配置</button></div><div class="risk-rule-grid"><div><span>最大单股仓位</span><strong>{{ store.config.maxSingleWeight }}%</strong></div><div><span>最大总仓位</span><strong>{{ store.config.maxTotalWeight }}%</strong></div><div><span>最大持仓数量</span><strong>{{ store.config.maxPositions }} 只</strong></div><div><span>最大单笔金额</span><strong>{{ money(store.config.maxOrderAmount) }}</strong></div><div><span>单股止损</span><strong>-{{ store.config.stopLoss }}%</strong></div><div><span>单股止盈</span><strong>+{{ store.config.takeProfit }}%</strong></div><div><span>账户单日最大亏损</span><strong>-{{ store.config.maxDailyLoss }}%</strong></div><div class="kill-rule"><span>策略 Kill Switch</span><strong>-{{ store.config.maxDrawdown }}%</strong></div><div><span>重复交易冷却</span><strong>{{ store.config.cooldownMinutes }} 分钟</strong></div></div></section><section class="panel"><div class="panel-head"><div><h2>交易成本假设</h2><p>均为可配置模拟参数</p></div></div><div class="cost-list"><div><span>佣金率</span><strong>{{ (store.config.commissionRate*100).toFixed(3) }}%</strong></div><div><span>最低佣金</span><strong>{{ money(store.config.minimumCommission) }}</strong></div><div><span>卖出税费</span><strong>{{ (store.config.taxRate*100).toFixed(3) }}%</strong></div><div><span>滑点</span><strong>{{ store.config.slippageBps }} bps</strong></div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Risk Events</h2><p>每次拒单、警告或停机都留下可审计记录</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>时间</th><th>级别</th><th>风险规则</th><th>具体原因</th><th>系统动作</th></tr></thead><tbody><tr v-for="row in store.riskEvents" :key="row.id"><td class="mono muted">{{ row.time }}</td><td><SignalTag :text="row.severity" :tone="row.severity === 'HALT' ? 'negative' : row.severity === 'WARNING' ? 'warning' : 'info'" /></td><td><strong>{{ row.rule }}</strong></td><td>{{ row.detail }}</td><td>{{ row.action }}</td></tr></tbody></table></div></section>
  </template>

  <template v-else-if="activeTab === '绩效'">
    <div class="performance-metrics section-gap"><MetricCard label="累计收益" :value="pct(store.cumulativeReturn)" tone="positive" hint="虚拟净值" /><MetricCard label="年化收益" value="18.42%" change="演示估算" tone="positive" hint="样本期不足一年" /><MetricCard label="最大回撤" :value="pct(store.maxDrawdown)" tone="negative" hint="峰值至谷值" /><MetricCard label="波动率" value="16.7%" hint="年化演示值" /><MetricCard label="胜率" value="61.5%" change="8 / 13" tone="positive" hint="已结束交易" /><MetricCard label="Profit Factor" value="1.86" hint="总盈利 / 总亏损" /><MetricCard label="平均持有" value="6.8天" hint="已结束交易" /><MetricCard label="资金利用率" :value="`${store.totalWeight.toFixed(1)}%`" hint="当前虚拟仓位" /></div><section class="panel section-gap"><div class="panel-head"><div><h2>策略与基准</h2><p>Strategy NAV vs 沪深300 Demo Benchmark</p></div><SignalTag text="演示数据" tone="warning" /></div><div class="chart-panel"><EChart :option="navOption" height="330px" /></div></section><div class="grid-2 section-gap"><section class="panel"><div class="panel-head"><div><h2>回撤曲线</h2><p>触发 -{{ store.config.maxDrawdown }}% 时启用 Kill Switch</p></div></div><div class="chart-panel"><EChart :option="drawdownOption" height="250px" /></div></section><section class="panel"><div class="panel-head"><div><h2>月度收益</h2><p>演示样本，不代表实际策略表现</p></div></div><div class="chart-panel"><EChart :option="monthlyOption" height="250px" /></div></section></div>
  </template>

  <template v-else-if="activeTab === '运行日志'">
    <section class="panel section-gap"><div class="panel-head"><div><h2>Quant Runtime Logs</h2><p>策略、信号、风控、订单与成交的完整可解释链路</p></div><div class="log-filters"><button v-for="level in ['ALL','INFO','SIGNAL','ORDER','TRADE','RISK','ERROR']" :key="level" :class="{ active: logFilter === level }" @click="logFilter = level as typeof logFilter">{{ level }}</button></div></div><div class="runtime-logs"><article v-for="row in filteredLogs" :key="row.id"><time>{{ row.time }}</time><SignalTag :text="row.level" :tone="row.level === 'ERROR' ? 'negative' : row.level === 'RISK' ? 'warning' : row.level === 'TRADE' ? 'positive' : row.level === 'SIGNAL' ? 'info' : 'neutral'" /><div><strong>{{ row.message }}</strong><p v-if="row.detail">{{ row.detail }}</p></div></article></div></section>
  </template>

